{
	"name": "main protection",
	"target": "branch",
	"enforcement": "active",
	"conditions": {
		"ref_name": {
			"include": ["~DEFAULT_BRANCH"],
			"exclude": []
		}
	},
	"rules": [
		{ "type": "deletion" },
		{ "type": "non_fast_forward" },
		{ "type": "required_linear_history" },
		{
			"type": "pull_request",
			"parameters": {
				"required_approving_review_count": 1,
				"dismiss_stale_reviews_on_push": true,
				"require_code_owner_review": true,
				"require_last_push_approval": false,
				"required_review_thread_resolution": true
			}
		},
		{
			"type": "required_status_checks",
			"parameters": {
				"strict_required_status_checks_policy": true,
				"required_status_checks": [
					{ "context": "test (ubuntu-latest · node 20)" },
					{ "context": "test (ubuntu-latest · node 22)" },
					{ "context": "test (macos-latest · node 20)" },
					{ "context": "test (macos-latest · node 22)" }
				]
			}
		}
	],
	"bypass_actors": [
		{
			"actor_id": 5,
			"actor_type": "RepositoryRole",
			"bypass_mode": "always"
		}
	]
}

{
	"$schema": "https://biomejs.dev/schemas/2.4.16/schema.json",
	"linter": {
		"enabled": true,
		"rules": {
			"recommended": true,
			"style": {
				"noDefaultExport": "error",
				"noEnum": "error",
				"noNonNullAssertion": "error",
				"useImportType": "error",
				"useConst": "error",
				"useNodejsImportProtocol": "off"
			},
			"complexity": {
				"useLiteralKeys": "off"
			},
			"suspicious": {
				"noExplicitAny": "error",
				"noTsIgnore": "error",
				"noControlCharactersInRegex": "off",
				"noEmptyInterface": "off"
			}
		}
	},
	"formatter": {
		"enabled": true,
		"formatWithErrors": false,
		"indentStyle": "tab",
		"indentWidth": 3,
		"lineWidth": 120
	},
	"files": {
		"includes": ["src/**/*.ts", "test/**/*.ts", "vitest.config.ts", "!**/node_modules/**/*", "!**/dist/**/*"]
	},
	"overrides": [
		{
			"includes": ["vitest.config.ts"],
			"linter": {
				"rules": {
					"style": {
						"noDefaultExport": "off"
					}
				}
			}
		}
	]
}

